    private inline fun imageVector(name: String, block: ImageVector.Builder.() -> Unit): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        )
            .apply(block)
            .build()

    private fun ImageVector.Builder.svgPath(
        data: String,
        fill: Color? = null,
        stroke: Color? = null,
        strokeWidth: Float = 0f,
        strokeLineCap: StrokeCap = StrokeCap.Butt,
        strokeLineJoin: StrokeJoin = StrokeJoin.Miter,
    ) = addPath(
        pathData = addPathNodes(data),
        pathFillType = PathFillType.EvenOdd,
        fill = fill?.let(::SolidColor),
        stroke = stroke?.let(::SolidColor),
        strokeLineWidth = strokeWidth,
        strokeLineCap = strokeLineCap,
        strokeLineJoin = strokeLineJoin,
    )
}
